package com.bank.qa.payment;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Enforces idempotency, authoritative state, declines, and capped refunds.
class PaymentGateway {
    private static final Logger log = Logger.getLogger(PaymentGateway.class.getName());

    // Idempotency store: key -> the ORIGINAL result (source of truth).
    private final Map<String, PaymentResult> byKey = new HashMap<>();
    // Captured amount per reference, to cap refunds.
    private final Map<String, BigDecimal> captured = new HashMap<>();
    private final Map<String, BigDecimal> refunded = new HashMap<>();
    private BigDecimal payerBalance = new BigDecimal("250000"); // Priya CUR3001

    // charge is IDEMPOTENT on idempotencyKey — resend never double-charges.
    PaymentResult charge(String idempotencyKey, Card card, BigDecimal amount) {
        if (byKey.containsKey(idempotencyKey)) {
            log.warning(() -> "Duplicate key " + idempotencyKey + " -> echo original, NO second charge");
            PaymentResult orig = byKey.get(idempotencyKey);
            return new PaymentResult(PaymentResult.Status.DUPLICATE_ECHO, orig.getAmount(), orig.getReference());
        }
        PaymentResult result;
        if (card.expired) {
            result = new PaymentResult(PaymentResult.Status.DECLINED_CARD, amount, null);
        } else if (!card.cvvValid) {
            result = new PaymentResult(PaymentResult.Status.DECLINED_CVV, amount, null);
        } else if (payerBalance.compareTo(amount) < 0) {
            result = new PaymentResult(PaymentResult.Status.DECLINED_INSUFFICIENT, amount, null);
        } else {
            payerBalance = payerBalance.subtract(amount);
            String ref = "TXN-" + (byKey.size() + 1);
            captured.put(ref, amount);
            result = new PaymentResult(PaymentResult.Status.CAPTURED, amount, ref);
            log.info(() -> "CAPTURED " + amount + " ref=" + ref);
        }
        byKey.put(idempotencyKey, result); // store authoritative outcome
        return result;
    }

    // Refund capped at captured amount; supports partial refunds.
    PaymentResult refund(String reference, BigDecimal amount) {
        BigDecimal cap = captured.getOrDefault(reference, BigDecimal.ZERO);
        BigDecimal already = refunded.getOrDefault(reference, BigDecimal.ZERO);
        if (already.add(amount).compareTo(cap) > 0) {
            log.severe(() -> "Refund exceeds captured for " + reference + " -> rejected");
            return new PaymentResult(PaymentResult.Status.DECLINED_INSUFFICIENT, amount, reference);
        }
        refunded.put(reference, already.add(amount));
        payerBalance = payerBalance.add(amount);
        return new PaymentResult(PaymentResult.Status.REFUNDED, amount, reference);
    }

    BigDecimal payerBalance() { return payerBalance; }
}
