package com.bank.qa.payment;

import java.util.logging.*;

public class PaymentTestDemo {
    private static final Logger log = Logger.getLogger(PaymentTestDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new PaymentLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        log.info("=== Payment gateway test suite (financial correctness) ===");
        new PaymentTestSuite().runAll();
        log.info("Reliability cases requiring infra: timeout->status UNKNOWN+reconcile, "
            + "webhook callback failure->poll, browser-close->server state authoritative, "
            + "currency conversion rounding, status mismatch->gateway is authority.");
    }
}

